import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class FunctionType_getSuperClassConstructor_TriageGen0Test {

    @Test
    public void testGetSuperClassConstructor_ThrowsExceptionWhenNotConstructorOrInterface() {
        // Setup: a FunctionType that is neither a constructor nor an interface
        FunctionType functionType = mock(FunctionType.class);
        when(functionType.isConstructor()).thenReturn(false);
        when(functionType.isInterface()).thenReturn(false);

        try {
            functionType.getSuperClassConstructor();
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Success: Preconditions.checkArgument threw exception
        }
    }

    @Test
    public void testGetSuperClassConstructor_ReturnsNullWhenImplicitPrototypeIsNull() {
        // Setup: a FunctionType that is a constructor
        FunctionType functionType = mock(FunctionType.class);
        ObjectType prototype = mock(ObjectType.class);

        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.getPrototype()).thenReturn(prototype);
        when(prototype.getImplicitPrototype()).thenReturn(null);

        FunctionType result = functionType.getSuperClassConstructor();
        assertNull(result);
    }

    @Test
    public void testGetSuperClassConstructor_ReturnsConstructorWhenImplicitPrototypeExists() {
        // Setup: a FunctionType that is an interface
        FunctionType functionType = mock(FunctionType.class);
        ObjectType prototype = mock(ObjectType.class);
        ObjectType implicitPrototype = mock(ObjectType.class);
        FunctionType expectedConstructor = mock(FunctionType.class);

        when(functionType.isInterface()).thenReturn(true);
        when(functionType.getPrototype()).thenReturn(prototype);
        when(prototype.getImplicitPrototype()).thenReturn(implicitPrototype);
        when(implicitPrototype.getConstructor()).thenReturn(expectedConstructor);

        FunctionType result = functionType.getSuperClassConstructor();
        assertEquals(expectedConstructor, result);
    }

    @Test
    public void testGetSuperClassConstructor_ReturnsConstructorWhenIsConstructorIsTrue() {
        // Setup: a FunctionType that is a constructor
        FunctionType functionType = mock(FunctionType.class);
        ObjectType prototype = mock(ObjectType.class);
        ObjectType implicitPrototype = mock(ObjectType.class);
        FunctionType expectedConstructor = mock(FunctionType.class);

        when(functionType.isConstructor()).thenReturn(true);
        when(functionType.getPrototype()).thenReturn(prototype);
        when(prototype.getImplicitPrototype()).thenReturn(implicitPrototype);
        when(implicitPrototype.getConstructor()).thenReturn(expectedConstructor);

        FunctionType result = functionType.getSuperClassConstructor();
        assertEquals(expectedConstructor, result);
    }
}
